// Solo crea tickets. El registro / login / recuperación viven en el flujo 04.
const b = $json.body ?? $json;
const txt = (v, max) => String(v ?? '').trim().slice(0, max);
const d = {
  session_token: txt(b.session_token, 200),
  nombre: txt(b.nombre ?? b.nombre_completo ?? b.name, 150),
  identificacion: txt(b.identificacion ?? b.cedula, 50),
  telefono: txt(b.telefono ?? b.phone, 30),
  tipo_dispositivo: txt(b.tipo_dispositivo, 100),
  descripcion: txt(b.descripcion ?? b.descripcion_problema, 5000),
  direccion: txt(b.direccion, 300),
  // 'chat': el caso se inició escribiendo directamente en el chat web
  canal: b.canal === 'chat' ? 'chat' : 'web',
};
let error = '', status = 'invalid';
if (!d.session_token) { error = 'Inicia sesión para crear una solicitud.'; status = 'unauthorized'; }
else if (d.descripcion.length < 10) error = 'Describe el problema con al menos 10 caracteres.';
return [{ json: { ...d, error, status } }];

// Prioridad por reglas: palabras del problema + casos abiertos del cliente.
// Crítica: riesgo para la persona · Alta: no puede usar el equipo o hay pérdida de datos
// Media: falla parcial · Baja: consultas y configuraciones.
const NOMBRES_PRIORIDAD = { 4: 'Crítica', 3: 'Alta', 2: 'Media', 1: 'Baja' };
const HORAS_SLA = { 4: 4, 3: 24, 2: 48, 1: 72 };
function normalizarTexto(s) {
  return String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
}
function calcularPrioridad(texto, extra = {}) {
  const s = normalizarTexto(texto);
  const reglas = [
    [4, /(humo|fuego|llama|olor a quemado|quemad[oa]|chispa|bateria (hinchada|inflada)|descarga electrica|corto ?circuito|explot)/],
    [3, /(no (enciende|prende|arranca|inicia)|pantalla (rota|partida|quebrada|negra)|liquido|derram|mojad[oa]|se (me )?mojo|virus|hacke|ransomware|secuestr|perdi (mis |los |la )?(archivos|informacion|datos)|urgente|no puedo trabajar|se (me )?cayo|golpe)/],
    [2, /(lent|wifi|internet|\bred\b|impresora|no imprime|error|pantallazo|se congela|se reinicia|sonido|audio|teclado|mouse|touchpad|bateria|cargador|no carga|camara|monitor)/],
  ];
  let puntaje = 1, motivo = 'Consulta o configuración';
  for (const [p, re] of reglas) {
    const m = s.match(re);
    if (m) { puntaje = p; motivo = `Palabra clave: "${m[0]}"`; break; }
  }
  if (Number(extra.abiertos || 0) >= 2 && puntaje < 4) { puntaje += 1; motivo += ' + varios casos abiertos'; }
  if (extra.minimo && extra.minimo > puntaje) { puntaje = extra.minimo; motivo = extra.motivoMinimo || motivo; }
  return { prioridad: NOMBRES_PRIORIDAD[puntaje], puntaje_prioridad: puntaje, horas_sla: HORAS_SLA[puntaje],
           motivo_prioridad: motivo.slice(0, 120) };
}

const req = $('Validar y normalizar solicitud').first().json;
const s = $input.first().json;
let ok = !req.error && !!s.usuario_id;
let respuesta = null;
if (req.error) respuesta = { success: false, status: req.status, message: req.error };
else if (!s.usuario_id) respuesta = { success: false, status: 'unauthorized', message: 'Tu sesión expiró. Inicia sesión nuevamente.' };
const prioridad = calcularPrioridad(`${req.descripcion} ${req.tipo_dispositivo}`, { abiertos: s.abiertos });
return [{ json: { ...req, ...s, ...prioridad, nombre: req.nombre || s.usuario_nombre,
  identificacion: req.identificacion || s.usuario_identificacion || '',
  telefono: req.telefono || s.usuario_telefono || '', ok, respuesta } }];

// Prioridad por reglas: palabras del problema + casos abiertos del cliente.
// Crítica: riesgo para la persona · Alta: no puede usar el equipo o hay pérdida de datos
// Media: falla parcial · Baja: consultas y configuraciones.
const NOMBRES_PRIORIDAD = { 4: 'Crítica', 3: 'Alta', 2: 'Media', 1: 'Baja' };
const HORAS_SLA = { 4: 4, 3: 24, 2: 48, 1: 72 };
